import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.DXa1R37q.js";const u=JSON.parse('{"title":"Native harness extensions","description":"","frontmatter":{},"headers":[],"relativePath":"harnesses/index.md","filePath":"harnesses/index.md","lastUpdated":1792947882000}'),o={name:"harnesses/index.md"};function r(i,e,c,d,h,p){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="native-harness-extensions" tabindex="-1">Native harness extensions <a class="header-anchor" href="#native-harness-extensions" aria-label="Permalink to &quot;Native harness extensions&quot;">​</a></h1><p>Neottia ships native extensions for Pi and OpenCode. Each host has Memory, Issues, Design Docs, and Searchable packages. Native means the host loads the package in process.</p><ul><li><a href="/projects/neottia/harnesses/pi">Configure Pi</a></li><li><a href="/projects/neottia/harnesses/opencode">Configure OpenCode</a></li><li><a href="/projects/neottia/harnesses/claude-code">Configure Claude Code</a></li><li><a href="/projects/neottia/harnesses/adapters">Use the declarative adapter contract</a></li></ul><p><code>@neottia/harness-adapter</code> keeps host paths and configuration formats out of generated SDLC content and installation logic. The Pi, OpenCode, and Claude Code adapters publish exact feature support and return reviewable plans.</p><p>Other clients may use the <a href="/projects/neottia/mcp/">generic MCP servers</a> if they can launch a stdio MCP process. Searchable is available through <code>@neottia/searchable-mcp</code> and the native <code>@neottia/pi-searchable</code> and <code>@neottia/opencode-searchable</code> adapters.</p>',5)])])}const f=a(o,[["render",r]]);export{u as __pageData,f as default};
